import {
  ActivityIndicator, Alert, FlatList, Image, ImageBackground, KeyboardAvoidingView, Modal, Platform, Pressable, SafeAreaView, ScrollView,
  StatusBar as NativeStatusBar, StyleSheet, Text, TextInput, View,
} from 'react-native';
import { StatusBar } from 'expo-status-bar';
import * as ImagePicker from 'expo-image-picker';
import NetInfo from '@react-native-community/netinfo';
import Ionicons from '@expo/vector-icons/Ionicons';
import { getDisease } from './src/data';
import { analyzeLeaf } from './src/services/inference';
import { deleteDiagnosis, deleteDiagnosesForOwner, initializeDatabase, listDiagnoses, markSynced, saveDiagnosis } from './src/services/database';
import { syncDiagnoses } from './src/services/sync';
import { authenticate, changePassword, deleteAccount, logoutSession, restoreSession, updateProfile } from './src/services/auth';
import { loadDiseaseCatalog } from './src/services/diseases';
import { deletePersistedDiagnosisImage, persistDiagnosisImage } from './src/services/imageStorage';
import { Diagnosis, Disease, Session } from './src/types';

type Screen = 'home' | 'scan' | 'history' | 'guide' | 'profile';
const SAMPLE_IMAGE = require('./assets/black-sigatoka-sample.jpg');
const AUTH_BACKGROUND = require('./assets/banana-leaf-auth-background.jpg');
const BRAND_LOGO = require('./assets/dahonmd-logo-green.png');
const GOOGLE_LOGO = require('./assets/google-g.png');
const configuredConfidenceThreshold = Number(process.env.EXPO_PUBLIC_CONFIDENCE_THRESHOLD ?? 70);
const CONFIDENCE_THRESHOLD = Number.isFinite(configuredConfidenceThreshold)
  ? Math.min(100, Math.max(0, configuredConfidenceThreshold))
  : 70;
const COLORS = { ink: '#17211e', muted: '#6b7571', green: '#176348', dark: '#153f34', lime: '#b6cb56', bg: '#f2f5f2', line: '#dce2de', white: '#ffffff', amber: '#b97816', red: '#b84d45' };
const createSyncUuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (character) => { const random = Math.floor(Math.random() * 16); return (character === 'x' ? random : (random & 0x3) | 0x8).toString(16); });

function IconButton({ icon, label, onPress }: { icon: keyof typeof Ionicons.glyphMap; label: string; onPress: () => void }) {
  return <Pressable accessibilityRole="button" accessibilityLabel={label} style={({ pressed }) => [styles.iconButton, pressed && styles.pressed]} onPress={onPress}><Ionicons name={icon} size={21} color={COLORS.dark} /></Pressable>;
}

function Header({ online, pending }: { online: boolean; pending: number }) {
  return <View style={styles.header}><View style={styles.brandMark}><Ionicons name="leaf" size={20} color={COLORS.dark} /></View><View style={styles.brandCopy}><Text style={styles.brand}>DahonMD</Text><Text style={styles.brandSmall}>LEAF HEALTH GUIDE</Text></View><View style={[styles.networkPill, !online && styles.networkOffline]}><Ionicons name={online ? 'cloud-done-outline' : 'cloud-offline-outline'} size={15} color={online ? COLORS.green : COLORS.amber} /><Text style={[styles.networkText, !online && { color: COLORS.amber }]}>{online ? (pending ? `${pending} waiting` : 'Saved online') : 'Offline'}</Text></View></View>;
}

function SectionTitle({ title, action }: { eyebrow?: string; title: string; action?: React.ReactNode }) {
  return <View style={styles.sectionHeading}><Text style={styles.sectionTitle}>{title}</Text>{action}</View>;
}

function DiagnosisCard({ item, onOpen, catalog }: { item: Diagnosis; onOpen: () => void; catalog: Disease[] }) {
  const disease = getDisease(item.diseaseId, catalog);
  return <Pressable accessibilityRole="button" accessibilityLabel={`Open scan from ${new Date(item.diagnosedAt).toLocaleDateString()}`} style={({ pressed }) => [styles.diagnosisCard, pressed && styles.pressed]} onPress={onOpen}>
    <View style={[styles.diagnosisThumb, { backgroundColor: disease.status === 'healthy' ? '#e4f0e9' : '#faefd8' }]}>{item.imageUri ? <Image source={{ uri: item.imageUri }} style={styles.fillImage} /> : <Ionicons name="leaf-outline" size={22} color={COLORS.green} />}</View>
    <View style={styles.flex}><Text style={styles.cardTitle}>{item.confidence < CONFIDENCE_THRESHOLD ? 'Uncertain result' : disease.name}</Text><Text style={styles.cardMeta}>{item.confidence < CONFIDENCE_THRESHOLD ? 'Try another clear photo' : item.confidence >= 85 ? 'High confidence' : 'Moderate confidence'} · {new Date(item.diagnosedAt).toLocaleDateString()}</Text></View>
    <View style={styles.scoreRight}><Text style={styles.score}>{item.confidence.toFixed(1)}%</Text><View style={styles.syncLabel}><Ionicons name={item.synced ? 'cloud-done-outline' : 'cloud-offline-outline'} size={12} color={COLORS.muted} /><Text style={styles.tiny}>{item.synced ? 'Saved online' : 'Waiting to sync'}</Text></View></View>
    <Ionicons name="chevron-forward" size={17} color="#9ca7a2" style={styles.cardChevron} />
  </Pressable>;
}

function HomeScreen({ records, online, setScreen, openRecord, name, catalog }: { records: Diagnosis[]; online: boolean; setScreen: (screen: Screen) => void; openRecord: (record: Diagnosis) => void; name: string; catalog: Disease[] }) {
  return <ScrollView contentContainerStyle={styles.page} showsVerticalScrollIndicator={false}>
    <View style={styles.greeting}><View><Text style={styles.eyebrow}>HOME</Text><Text style={styles.h1}>Hello, {name}.</Text><Text style={styles.subtitle}>Check your banana leaf for possible disease.</Text></View></View>
    <View style={styles.hero}><View style={styles.heroBadge}><Ionicons name="camera" size={14} color={COLORS.lime} /><Text style={styles.heroBadgeText}>START HERE</Text></View><Text style={styles.heroTitle}>Scan Banana Leaf</Text><Text style={styles.heroText}>Take a photo or choose one from your gallery.</Text><Pressable accessibilityRole="button" accessibilityLabel="Scan banana leaf" style={styles.heroButton} onPress={() => setScreen('scan')}><Ionicons name="camera" size={21} color={COLORS.dark} /><Text style={styles.heroButtonText}>Scan Banana Leaf</Text></Pressable><View style={styles.heroStatus}><Ionicons name={online ? 'cloud-done-outline' : 'cloud-offline-outline'} size={16} color="#dce8a8" /><Text style={styles.heroStatusText}>{online ? 'Saved scans can sync online' : 'Offline mode · scans stay on this device'}</Text></View></View>
    <SectionTitle eyebrow="RECENT SCANS" title="Latest results" action={<Pressable onPress={() => setScreen('history')}><Text style={styles.textLink}>View all</Text></Pressable>} />
    <View style={styles.listCard}>{records.slice(0, 4).map((record) => <DiagnosisCard key={record.id} item={record} catalog={catalog} onOpen={() => openRecord(record)} />)}{!records.length && <View style={styles.empty}><Ionicons name="leaf-outline" size={32} color="#90a099" /><Text style={styles.emptyTitle}>No scans yet.</Text><Text style={styles.emptyText}>Scan your first banana leaf to start your history.</Text></View>}</View>
    <View style={styles.fieldNote}><Ionicons name={online ? 'cloud-done-outline' : 'cloud-offline-outline'} size={20} color={online ? COLORS.green : COLORS.amber} /><Text style={styles.fieldNoteText}>{online ? 'All synchronized scans are saved online.' : 'You can still scan leaves. Results are saved on this device and uploaded when your connection returns.'}</Text></View>
  </ScrollView>;
}

function ScanScreen({ online, onSaved, goHome, ownerId, catalog }: { online: boolean; onSaved: (record: Diagnosis) => Promise<void>; goHome: () => void; ownerId: number; catalog: Disease[] }) {
  const [imageUri, setImageUri] = useState<string | null>(null);
  const [isSample, setIsSample] = useState(false);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [result, setResult] = useState<Awaited<ReturnType<typeof analyzeLeaf>> | null>(null);

  const choose = async (camera: boolean) => {
    try {
      if (camera) {
        const permission = await ImagePicker.requestCameraPermissionsAsync();
        if (!permission.granted) {
          Alert.alert('Camera permission required', 'Enable camera access in your device settings to photograph a banana leaf.');
          return;
        }
      }

      const picker = camera ? ImagePicker.launchCameraAsync : ImagePicker.launchImageLibraryAsync;
      const response = await picker({ mediaTypes: ['images'], quality: 0.85, allowsEditing: false, cameraType: ImagePicker.CameraType.back });
      const selectedUri = response.assets?.[0]?.uri;
      if (!response.canceled && selectedUri) {
        setImageUri(selectedUri);
        setIsSample(false);
        setResult(null);
      }
    } catch (error) {
      Alert.alert('Unable to open image', error instanceof Error ? error.message : 'Try again.');
    }
  };
  const useSample = () => { setImageUri(Image.resolveAssetSource(SAMPLE_IMAGE).uri); setIsSample(true); setResult(null); };
  const analyze = async () => {
    if (!imageUri || loading) return;
    setLoading(true);
    try {
      setResult(await analyzeLeaf(imageUri));
    } catch (error) {
      Alert.alert('Unable to analyze image', error instanceof Error ? error.message : 'Try another photo.');
    } finally {
      setLoading(false);
    }
  };
  const save = async () => {
    if (!result || saving) return;
    setSaving(true);
    const id = createSyncUuid();
    let persistedImageUri: string | null = null;

    try {
      persistedImageUri = isSample || !imageUri ? null : persistDiagnosisImage(imageUri, id);
      const diagnosis: Diagnosis = { id, ownerId, diseaseId: result.diseaseId, confidence: result.confidence, latency: result.latency, imageUri: persistedImageUri, modelVersion: result.modelVersion, diagnosedAt: new Date().toISOString(), synced: false, isSimulated: result.isSimulated };
      await onSaved(diagnosis);
      Alert.alert('Saved locally', online ? 'The result is queued for mobile API sync.' : 'It will sync when a connection is available.', [{ text: 'Done', onPress: goHome }]);
    } catch (error) {
      deletePersistedDiagnosisImage(persistedImageUri);
      Alert.alert('Unable to save result', error instanceof Error ? error.message : 'Free some device storage and try again.');
    } finally {
      setSaving(false);
    }
  };
  if (result && imageUri) return <ResultView imageUri={imageUri} result={result} catalog={catalog} saving={saving} onSave={save} onReset={() => { setResult(null); setImageUri(null); }} />;
  return <ScrollView contentContainerStyle={styles.page} showsVerticalScrollIndicator={false}><View style={styles.screenTop}><View><Text style={styles.eyebrow}>SCAN</Text><Text style={styles.h1}>Scan Banana Leaf</Text><Text style={styles.subtitle}>Take a photo or choose one from your gallery.</Text></View></View>
    <View style={styles.captureFrame}>{imageUri ? <Image source={{ uri: imageUri }} style={styles.captureImage} /> : <><View style={styles.cornerTL} /><View style={styles.cornerTR} /><View style={styles.cornerBL} /><View style={styles.cornerBR} /><View style={styles.leafCircle}><Ionicons name="leaf-outline" size={46} color={COLORS.green} /></View><Text style={styles.captureTitle}>Use one leaf at a time</Text><Text style={styles.captureHint}>Use good lighting. Keep the affected area visible and avoid blurry photos.</Text></>}{loading && <View style={styles.loadingCover}><ActivityIndicator color={COLORS.lime} size="large" /><Text style={styles.loadingTitle}>Checking the leaf...</Text><Text style={styles.loadingText}>We are examining visible patterns on the leaf.</Text></View>}</View>
    {!imageUri ? <><Pressable style={styles.primary} onPress={() => choose(true)}><Ionicons name="camera" size={20} color={COLORS.white} /><Text style={styles.primaryText}>Take Photo</Text></Pressable><View style={styles.secondaryRow}><Pressable style={styles.secondary} onPress={() => choose(false)}><Ionicons name="images-outline" size={19} color={COLORS.dark} /><Text style={styles.secondaryText}>Choose from Gallery</Text></Pressable><Pressable style={styles.secondary} onPress={useSample}><Ionicons name="flask-outline" size={19} color={COLORS.dark} /><Text style={styles.secondaryText}>Development Sample</Text></Pressable></View></> : <><Pressable style={styles.primary} disabled={loading} onPress={analyze}><Ionicons name="checkmark-circle-outline" size={20} color={COLORS.white} /><Text style={styles.primaryText}>Use This Photo</Text></Pressable><Pressable style={styles.changeImage} onPress={() => { setImageUri(null); setResult(null); }}><Text style={styles.textLink}>Retake or choose another photo</Text></Pressable></>}
    <View style={styles.checkRow}>{[['leaf-outline','One leaf'],['sunny-outline','Natural light'],['aperture-outline','Sharp focus']].map(([icon,label]) => <View style={styles.checkItem} key={label}><Ionicons name={icon as keyof typeof Ionicons.glyphMap} size={15} color={COLORS.green} /><Text style={styles.checkText}>{label}</Text></View>)}</View>
    <View style={styles.demoNotice}><Ionicons name="information-circle-outline" size={18} color={COLORS.amber} /><Text style={styles.demoText}>This development version uses a simulated result. It does not confirm a plant disease.</Text></View>
  </ScrollView>;
}

function ResultView({ imageUri, result, saving, onSave, onReset, catalog }: { imageUri: string; result: Awaited<ReturnType<typeof analyzeLeaf>>; saving: boolean; onSave: () => Promise<void>; onReset: () => void; catalog: Disease[] }) {
  const disease = getDisease(result.diseaseId, catalog);
  const uncertain = result.isUncertain || result.confidence < CONFIDENCE_THRESHOLD;
  const healthy = result.diseaseId === 'healthy';
  const confidenceLabel = uncertain ? 'Uncertain result' : result.confidence >= 85 ? 'High confidence' : 'Moderate confidence';
  return <ScrollView contentContainerStyle={styles.page} showsVerticalScrollIndicator={false}><Pressable style={styles.back} onPress={onReset}><Ionicons name="arrow-back" size={18} color={COLORS.green} /><Text style={styles.textLink}>Scan another leaf</Text></Pressable><Text style={styles.eyebrow}>RESULT</Text><Text style={styles.h1}>{uncertain ? "We couldn't identify this leaf confidently." : healthy ? 'No supported disease pattern was strongly detected' : 'Possible Disease'}</Text>
    <View style={styles.resultImageWrap}><Image source={{ uri: imageUri }} style={styles.resultImage} /></View>
    <View style={[styles.resultCard, uncertain && styles.uncertainCard]}>{!uncertain && <View style={styles.resultHeader}><View style={styles.alertIcon}><Ionicons name={healthy ? 'checkmark-circle-outline' : 'warning-outline'} size={22} color={healthy ? COLORS.green : COLORS.red} /></View><View style={styles.flex}><Text style={styles.detected}>{healthy ? 'SCREENING RESULT' : 'POSSIBLE DISEASE'}</Text><Text style={styles.resultDisease}>{disease.name}</Text></View></View>}<View style={styles.confidenceRow}><Text style={styles.confidenceLabel}>{confidenceLabel}</Text><Text style={styles.confidence}>{result.confidence.toFixed(1)}%</Text></View><View style={styles.progress}><View style={[styles.progressFill, uncertain && { backgroundColor: COLORS.amber }, { width: `${result.confidence}%` }]} /></View><Text style={styles.resultExplanation}>{uncertain ? 'The system could not make a confident match. Try another clear photo. No disease-specific management is shown.' : 'The image matched visual patterns learned for this supported class. Model confidence is not the probability that the plant truly has the disease.'}</Text></View>
    {uncertain ? <View style={styles.guidance}><Text style={styles.eyebrow}>TRY AGAIN WITH</Text>{['Better lighting', 'One leaf centered in the image', 'The affected area clearly visible', 'Less blur'].map((tip) => <View style={styles.symptom} key={tip}><Ionicons name="checkmark-circle-outline" size={17} color={COLORS.green} /><Text style={styles.symptomText}>{tip}</Text></View>)}<Pressable style={styles.primary} onPress={onReset}><Text style={styles.primaryText}>Take Another Photo</Text></Pressable></View> : disease.isVerified ? <><View style={styles.guidance}><Text style={styles.eyebrow}>WHAT THIS MEANS</Text><Text style={styles.actionText}>{healthy ? 'No supported disease pattern was strongly detected in this image. The model covers only its trained classes, so continue monitoring the plant.' : disease.summary}</Text><Text style={[styles.eyebrow, { marginTop: 20 }]}>WHAT YOU MAY NOTICE</Text>{disease.symptoms.map((symptom) => <View style={styles.symptom} key={symptom}><View style={styles.symptomDot} /><Text style={styles.symptomText}>{symptom}</Text></View>)}</View><View style={styles.actionBox}><Ionicons name="shield-checkmark-outline" size={22} color={COLORS.green} /><View style={styles.flex}><Text style={styles.actionTitle}>What you can do</Text><Text style={styles.actionText}>{disease.management}</Text></View></View></> : <View style={styles.guidance}><Text style={styles.actionText}>No verified disease guidance is available for this result.</Text></View>}
    <View style={styles.disclaimerBox}><Ionicons name="information-circle-outline" size={20} color={COLORS.amber} /><Text style={styles.disclaimerText}>This result is a screening aid based on the supported image classes. Some plant diseases and nutrient or environmental problems can look similar. Seek confirmation from a qualified agriculture or plant-health professional when symptoms are severe, unusual, spreading rapidly, or the result is uncertain.</Text></View>
    <Pressable accessibilityRole="button" accessibilityLabel="Save result" style={styles.primary} disabled={saving} onPress={onSave}>{saving ? <ActivityIndicator color={COLORS.white} /> : <><Ionicons name="save-outline" size={20} color={COLORS.white} /><Text style={styles.primaryText}>Save Result</Text></>}</Pressable>
  </ScrollView>;
}

function HistoryScreen({ records, openRecord, catalog }: { records: Diagnosis[]; openRecord: (record: Diagnosis) => void; catalog: Disease[] }) {
  return <View style={styles.historyPage}><Text style={styles.eyebrow}>HISTORY</Text><Text style={styles.h1}>Your Saved Scans</Text><Text style={styles.subtitle}>{records.length} scans saved on this device · newest first</Text><FlatList data={records} style={[styles.listCard, styles.historyList]} keyExtractor={(record) => record.id} renderItem={({ item }) => <DiagnosisCard item={item} catalog={catalog} onOpen={() => openRecord(item)} />} initialNumToRender={12} maxToRenderPerBatch={10} windowSize={7} removeClippedSubviews={Platform.OS === 'android'} showsVerticalScrollIndicator={false} ListEmptyComponent={<View style={styles.empty}><Ionicons name="time-outline" size={34} color="#90a099" /><Text style={styles.emptyTitle}>No scans yet.</Text><Text style={styles.emptyText}>Scan your first banana leaf to start your history.</Text></View>} /></View>;
}

function GuideScreen({ catalog, loaded }: { catalog: Disease[]; loaded: boolean }) {
  const [selected, setSelected] = useState<Disease | null>(null);
  useEffect(() => { setSelected((current) => catalog.find((item) => item.id === current?.id) ?? catalog[0] ?? null); }, [catalog]);
  return <ScrollView contentContainerStyle={styles.page} showsVerticalScrollIndicator={false}><Text style={styles.eyebrow}>FIELD REFERENCE</Text><Text style={styles.h1}>Disease guide</Text><Text style={styles.subtitle}>Only verified disease information from the central evidence database is cached for offline reference.</Text>{!loaded && <ActivityIndicator color={COLORS.green} style={{ marginTop: 30 }} />}{loaded && !selected && <View style={styles.empty}><Ionicons name="book-outline" size={34} color="#90a099" /><Text style={styles.emptyTitle}>DISEASE CONTENT PENDING</Text><Text style={styles.emptyText}>A validated trained-model label map is not yet available. Disease guidance remains unavailable until the model artifact and sources are verified.</Text></View>}{selected && <><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.guideTabs}>{catalog.map((disease) => <Pressable key={disease.id} onPress={() => setSelected(disease)} style={[styles.guideTab, selected.id === disease.id && styles.guideTabActive]}><Ionicons name="leaf-outline" size={17} color={selected.id === disease.id ? COLORS.white : COLORS.green} /><Text style={[styles.guideTabText, selected.id === disease.id && { color: COLORS.white }]}>{disease.name}</Text></Pressable>)}</ScrollView><View style={styles.guideCard}><View style={[styles.guideIcon, selected.status === 'critical' && { backgroundColor: '#f8e5e3' }]}><Ionicons name="leaf" size={28} color={selected.status === 'critical' ? COLORS.red : COLORS.green} /></View><Text style={styles.guideTitle}>{selected.name}</Text><Text style={styles.scientific}>{selected.scientific}</Text><Text style={styles.guideSummary}>{selected.summary}</Text><Text style={styles.eyebrow}>WHAT IT LOOKS LIKE</Text>{selected.symptoms.map((symptom) => <View style={styles.symptom} key={symptom}><Ionicons name="checkmark-circle" size={17} color={COLORS.green} /><Text style={styles.symptomText}>{symptom}</Text></View>)}<View style={styles.actionBox}><Ionicons name="shield-checkmark-outline" size={22} color={COLORS.green} /><View style={styles.flex}><Text style={styles.actionTitle}>What you can do</Text><Text style={styles.actionText}>{selected.management}</Text><Text style={styles.actionTitle}>Image-only limitations</Text><Text style={styles.actionText}>{selected.imageOnlyLimitations}</Text><Text style={styles.actionTitle}>When to seek expert help</Text><Text style={styles.actionText}>{selected.professionalReferral}</Text></View></View></View></>}</ScrollView>;
}

function RecordModal({ record, onClose, onDelete, catalog }: { record: Diagnosis | null; onClose: () => void; onDelete: (id: string) => void; catalog: Disease[] }) {
  if (!record) return null;
  const disease = getDisease(record.diseaseId, catalog);
  return <Modal visible animationType="slide" presentationStyle="pageSheet" onRequestClose={onClose}><SafeAreaView style={styles.modalRoot}>
    <View style={styles.modalHeader}><View style={styles.modalHeaderCopy}><Text style={styles.eyebrow}>Screening record</Text><Text style={styles.modalId} numberOfLines={1} ellipsizeMode="middle">{record.id}</Text></View><IconButton icon="close" label="Close" onPress={onClose} /></View>
    <ScrollView contentContainerStyle={styles.modalPage} automaticallyAdjustKeyboardInsets>{record.imageUri ? <Image source={{ uri: record.imageUri }} style={styles.modalImage} /> : <View style={[styles.modalImage, styles.modalPlaceholder]}><Ionicons name="leaf-outline" size={46} color={COLORS.green} /></View>}<Text style={styles.resultDisease}>{record.confidence < CONFIDENCE_THRESHOLD ? 'Uncertain result' : disease.name}</Text><Text style={styles.scientific}>{disease.scientific}</Text><View style={styles.modalScore}><Text style={styles.confidenceLabel}>Model confidence</Text><Text style={styles.confidence}>{record.confidence.toFixed(1)}%</Text></View>{[['Date', new Date(record.diagnosedAt).toLocaleString()],['Inference', `${record.latency} ms`],['Model',record.modelVersion],['Mode',record.isSimulated ? 'SIMULATED / DEVELOPMENT' : 'Deployment'],['Cloud',record.synced ? 'Synced' : 'Saved locally']].map(([label,value]) => <View style={styles.detailRow} key={label}><Text style={styles.detailLabel}>{label}</Text><Text style={styles.detailValue}>{value}</Text></View>)}<View style={styles.actionBox}><Ionicons name="shield-checkmark-outline" size={22} color={COLORS.green} /><Text style={[styles.actionText, styles.flex]}>{record.confidence < CONFIDENCE_THRESHOLD ? 'No disease-specific management is shown for an uncertain result.' : disease.management}</Text></View><Pressable style={styles.deleteButton} onPress={() => Alert.alert('Delete diagnosis?', 'This removes the local record from this device.', [{ text: 'Cancel', style: 'cancel' }, { text: 'Delete', style: 'destructive', onPress: () => onDelete(record.id) }])}><Ionicons name="trash-outline" size={18} color={COLORS.red} /><Text style={styles.deleteText}>Delete local record</Text></Pressable></ScrollView>
  </SafeAreaView></Modal>;
}

function AuthScreen({ onAuthenticated }: { onAuthenticated: (session: Session) => void }) {
  const [signup, setSignup] = useState(false); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const [showPassword, setShowPassword] = useState(false); const [remember, setRemember] = useState(true); const [notice, setNotice] = useState('');
  const [form, setForm] = useState({ name: '', email: '', password: '', password_confirmation: '' });
  const submit = async () => { setBusy(true); setError(''); setNotice(''); try { onAuthenticated(await authenticate(signup ? 'register' : 'login', form, remember)); } catch (exception) { setError(exception instanceof Error ? exception.message : 'Authentication failed.'); } finally { setBusy(false); } };
  const unavailable = (feature: string) => { setError(''); setNotice(`${feature} is not available yet.`); };
  return <ImageBackground source={AUTH_BACKGROUND} style={styles.authRoot} resizeMode="cover"><SafeAreaView style={styles.authSafe}><StatusBar style="dark" /><KeyboardAvoidingView style={styles.authKeyboard} behavior={Platform.OS === 'ios' ? 'padding' : 'height'}><ScrollView contentContainerStyle={styles.authContent} keyboardShouldPersistTaps="handled" showsVerticalScrollIndicator={false}><View style={styles.authBrandLockup}><Image source={BRAND_LOGO} style={styles.authLogo} resizeMode="contain" /><Text style={styles.authBrand}>Dahon<Text style={styles.authBrandAccent}>MD</Text></Text><Text style={styles.authTag}>Leaf health guide</Text></View><View style={styles.authWelcome}><View style={styles.authWelcomeTitle}><Ionicons name="leaf" size={20} color="#57b840" /><Text style={styles.authTitle}>{signup ? 'Create your account' : 'Welcome back!'}</Text></View><Text style={styles.authIntro}>{signup ? 'Save scans and access your leaf-health workspace.' : 'Sign in to continue checking the health of your banana plants.'}</Text></View><View style={styles.authCard}>{signup && <><Text style={styles.authLabel}>Full name</Text><View style={styles.authField}><Ionicons name="person-outline" size={18} color="#3aa156" /><TextInput style={styles.authFieldInput} placeholder="Your name" placeholderTextColor="#98a59f" value={form.name} onChangeText={(name) => setForm({ ...form, name })} autoCapitalize="words" autoComplete="name" /></View></>}<Text style={styles.authLabel}>Email address</Text><View style={styles.authField}><Ionicons name="mail-outline" size={18} color="#3aa156" /><TextInput style={styles.authFieldInput} placeholder="you@example.com" placeholderTextColor="#98a59f" value={form.email} onChangeText={(email) => setForm({ ...form, email })} keyboardType="email-address" autoCapitalize="none" autoComplete="email" /></View><Text style={styles.authLabel}>Password</Text><View style={styles.authField}><Ionicons name="lock-closed-outline" size={18} color="#3aa156" /><TextInput style={styles.authFieldInput} placeholder="Enter your password" placeholderTextColor="#98a59f" value={form.password} onChangeText={(password) => setForm({ ...form, password })} secureTextEntry={!showPassword} autoComplete={signup ? 'new-password' : 'current-password'} /><Pressable accessibilityRole="button" accessibilityLabel={showPassword ? 'Hide password' : 'Show password'} hitSlop={8} style={styles.authPasswordButton} onPress={() => setShowPassword(!showPassword)}><Ionicons name={showPassword ? 'eye-off-outline' : 'eye-outline'} size={20} color="#31824d" /></Pressable></View>{signup && <><Text style={styles.authLabel}>Confirm password</Text><View style={styles.authField}><Ionicons name="lock-closed-outline" size={18} color="#3aa156" /><TextInput style={styles.authFieldInput} placeholder="Repeat your password" placeholderTextColor="#98a59f" value={form.password_confirmation} onChangeText={(password_confirmation) => setForm({ ...form, password_confirmation })} secureTextEntry={!showPassword} autoComplete="new-password" /></View></>}<View style={styles.authOptions}><Pressable style={styles.rememberRow} onPress={() => setRemember(!remember)}><View style={[styles.rememberBox, remember && styles.rememberBoxActive]}>{remember && <Ionicons name="checkmark" size={12} color={COLORS.white} />}</View><Text style={styles.rememberText}>Remember me</Text></Pressable>{!signup && <Pressable onPress={() => unavailable('Password recovery')}><Text style={styles.forgotText}>Forgot password?</Text></Pressable>}</View>{Boolean(error || notice) && <Text style={error ? styles.formError : styles.authNotice} accessibilityRole="alert">{error || notice}</Text>}<Pressable style={({ pressed }) => [styles.primary, styles.authSubmit, pressed && styles.pressed]} disabled={busy} onPress={submit}>{busy ? <ActivityIndicator color={COLORS.white} /> : <><Ionicons name="leaf" size={18} color={COLORS.white} /><Text style={styles.primaryText}>{signup ? 'Create account' : 'Sign in'}</Text></>}</Pressable><View style={styles.authOr}><View style={styles.authOrLine} /><Text style={styles.authOrText}>or</Text><View style={styles.authOrLine} /></View><Pressable style={styles.googleButton} onPress={() => unavailable('Google sign-in')}><Image source={GOOGLE_LOGO} style={styles.googleLogo} resizeMode="contain" /><Text style={styles.googleText}>Continue with Google</Text></Pressable><Pressable style={styles.authSwitch} onPress={() => { setSignup(!signup); setError(''); setNotice(''); }}><Text style={styles.authSwitchLead}>{signup ? 'Already have an account? ' : 'New to DahonMD? '}<Text style={styles.authSwitchText}>{signup ? 'Sign in' : 'Create account'}  ›</Text></Text></Pressable></View></ScrollView></KeyboardAvoidingView></SafeAreaView></ImageBackground>;
}

function ProfileScreen({ session, onSession, onLogout, onDeleteAccount }: { session: Session; onSession: (session: Session) => void; onLogout: () => void; onDeleteAccount: () => Promise<void> }) {
  const [profile, setProfile] = useState({ name: session.user.name, email: session.user.email }); const [showPassword, setShowPassword] = useState(false);
  const [passwords, setPasswords] = useState({ current_password: '', password: '', password_confirmation: '' }); const [busy, setBusy] = useState(false);
  const saveProfile = async () => { setBusy(true); try { onSession(await updateProfile(session, profile)); Alert.alert('Profile updated'); } catch (exception) { Alert.alert('Unable to update', exception instanceof Error ? exception.message : 'Try again.'); } finally { setBusy(false); } };
  const savePassword = async () => { setBusy(true); try { await changePassword(session, passwords); setPasswords({ current_password: '', password: '', password_confirmation: '' }); setShowPassword(false); Alert.alert('Password updated'); } catch (exception) { Alert.alert('Unable to update', exception instanceof Error ? exception.message : 'Try again.'); } finally { setBusy(false); } };
  return <ScrollView contentContainerStyle={styles.page}><Text style={styles.eyebrow}>ACCOUNT</Text><Text style={styles.h1}>Profile</Text><View style={styles.profileAvatar}><Text style={styles.profileInitial}>{session.user.name.slice(0, 1).toUpperCase()}</Text></View><View style={styles.profileCard}><Text style={styles.inputLabel}>Name</Text><TextInput style={styles.input} value={profile.name} onChangeText={(name) => setProfile({ ...profile, name })} /><Text style={styles.inputLabel}>Email</Text><TextInput style={styles.input} value={profile.email} onChangeText={(email) => setProfile({ ...profile, email })} keyboardType="email-address" autoCapitalize="none" /><Pressable style={styles.primary} disabled={busy} onPress={saveProfile}><Text style={styles.primaryText}>Save profile</Text></Pressable><Pressable style={styles.profileAction} onPress={() => setShowPassword(!showPassword)}><Ionicons name="key-outline" size={18} color={COLORS.green} /><Text style={styles.profileActionText}>Change password</Text></Pressable>{showPassword && <View><TextInput style={styles.input} placeholder="Current password" secureTextEntry value={passwords.current_password} onChangeText={(current_password) => setPasswords({ ...passwords, current_password })} /><TextInput style={styles.input} placeholder="New password" secureTextEntry value={passwords.password} onChangeText={(password) => setPasswords({ ...passwords, password })} /><TextInput style={styles.input} placeholder="Confirm new password" secureTextEntry value={passwords.password_confirmation} onChangeText={(password_confirmation) => setPasswords({ ...passwords, password_confirmation })} /><Pressable style={styles.secondary} disabled={busy} onPress={savePassword}><Text style={styles.secondaryText}>Update password</Text></Pressable></View>}<Pressable style={styles.profileAction} onPress={onLogout}><Ionicons name="log-out-outline" size={18} color={COLORS.red} /><Text style={[styles.profileActionText, { color: COLORS.red }]}>Log out</Text></Pressable><Pressable style={styles.deleteButton} onPress={() => Alert.alert('Delete account?', 'This deletes the account, its server records, and this device’s saved scans.', [{ text: 'Cancel', style: 'cancel' }, { text: 'Delete', style: 'destructive', onPress: async () => { try { await onDeleteAccount(); } catch (exception) { Alert.alert('Unable to delete', exception instanceof Error ? exception.message : 'Connect to the Internet and try again.'); } } }])}><Text style={styles.deleteText}>Delete account</Text></Pressable></View></ScrollView>;
}

const TABS: { id: Screen; label: string; icon: keyof typeof Ionicons.glyphMap }[] = [{ id: 'home', label: 'Home', icon: 'home-outline' }, { id: 'scan', label: 'Scan', icon: 'scan-outline' }, { id: 'history', label: 'History', icon: 'time-outline' }, { id: 'guide', label: 'Guide', icon: 'book-outline' }, { id: 'profile', label: 'Profile', icon: 'person-outline' }];

export default function App() {
  const [screen, setScreen] = useState<Screen>('home'); const [records, setRecords] = useState<Diagnosis[]>([]); const [catalog, setCatalog] = useState<Disease[]>([]); const [catalogLoaded, setCatalogLoaded] = useState(false); const [online, setOnline] = useState(false); const [selected, setSelected] = useState<Diagnosis | null>(null); const [ready, setReady] = useState(false); const [session, setSession] = useState<Session | null>(null);
  const syncing = useRef(false);
  const refresh = useCallback(async () => setRecords(session ? await listDiagnoses(session.user.id) : []), [session]);
  useEffect(() => { Promise.all([initializeDatabase(), restoreSession()]).then(([, restored]) => setSession(restored)).finally(() => setReady(true)); const unsubscribe = NetInfo.addEventListener((state) => setOnline(Boolean(state.isConnected && state.isInternetReachable !== false))); return unsubscribe; }, []);
  useEffect(() => { refresh(); }, [refresh]);
  useEffect(() => { if (!ready) return; loadDiseaseCatalog().then(setCatalog).catch(() => setCatalog([])).finally(() => setCatalogLoaded(true)); }, [ready]);
  useEffect(() => {
    if (!session || !online || syncing.current || !records.some((record) => !record.synced)) return;
    syncing.current = true;
    const pendingRecords = records.filter((record) => !record.synced);
    syncDiagnoses(pendingRecords, session.token)
      .then(async (ids) => { if (!ids.length) return; await markSynced(ids); await refresh(); })
      .catch(() => undefined)
      .finally(() => { syncing.current = false; });
  }, [session, online, records, refresh]);
  const pending = useMemo(() => records.filter((record) => !record.synced).length, [records]);
  const addRecord = async (record: Diagnosis) => { await saveDiagnosis(record); await refresh(); };
  const removeRecord = async (id: string) => { const record = records.find((item) => item.id === id); await deleteDiagnosis(id); deletePersistedDiagnosisImage(record?.imageUri ?? null); setSelected(null); await refresh(); };
  if (!ready) return <View style={styles.boot}><View style={styles.bootMark}><Ionicons name="leaf" size={38} color={COLORS.dark} /></View><ActivityIndicator color={COLORS.lime} /><Text style={styles.bootText}>Preparing offline field data...</Text></View>;
  if (!session) return <AuthScreen onAuthenticated={setSession} />;
  const signOut = async () => { await logoutSession(session); setSession(null); setRecords([]); setScreen('home'); };
  const removeAccount = async () => { await deleteAccount(session); const imageUris = await deleteDiagnosesForOwner(session.user.id); imageUris.forEach(deletePersistedDiagnosisImage); setSession(null); setRecords([]); setScreen('home'); };
  return <SafeAreaView style={styles.safe}><StatusBar style="dark" /><NativeStatusBar backgroundColor={COLORS.white} barStyle="dark-content" /><Header online={online} pending={pending} /><View style={styles.content}>{screen === 'home' && <HomeScreen records={records} online={online} setScreen={setScreen} openRecord={setSelected} name={session.user.name.split(' ')[0]} catalog={catalog} />}{screen === 'scan' && <ScanScreen online={online} onSaved={addRecord} goHome={() => setScreen('home')} ownerId={session.user.id} catalog={catalog} />}{screen === 'history' && <HistoryScreen records={records} openRecord={setSelected} catalog={catalog} />}{screen === 'guide' && <GuideScreen catalog={catalog} loaded={catalogLoaded} />}{screen === 'profile' && <ProfileScreen session={session} onSession={setSession} onLogout={signOut} onDeleteAccount={removeAccount} />}</View><View style={styles.tabs} accessibilityRole="tablist">{TABS.map((tab) => <Pressable accessibilityRole="tab" accessibilityState={{ selected: screen === tab.id }} accessibilityLabel={tab.label} key={tab.id} style={styles.tab} onPress={() => setScreen(tab.id)}><View style={[styles.tabIcon, screen === tab.id && styles.tabIconActive]}><Ionicons name={screen === tab.id ? tab.icon.replace('-outline', '') as keyof typeof Ionicons.glyphMap : tab.icon} size={21} color={screen === tab.id ? COLORS.white : '#7d8984'} /></View><Text style={[styles.tabLabel, screen === tab.id && styles.tabLabelActive]}>{tab.label}</Text></Pressable>)}</View><RecordModal record={selected} onClose={() => setSelected(null)} onDelete={removeRecord} catalog={catalog} /></SafeAreaView>;
}

